/** Inactive terrain backend: world-free authored meshes, with Source UV and normal policy. */
@EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD,value=Dist.CLIENT)
public final class NativePropulsionModel {
 private static final int BUDGET=8*1024*1024,BINDINGS=8192;
 private NativePropulsionModel(){}
 private record Source(BakedModel model,List<PropulsionBoxMesh.Face> boxes,List<PropulsionObjMesh.Face> objects,boolean canonical){}
 private record Key(NativePropulsionAssets.Variant variant,int material,int brightness){}
 private record Mesh(List<List<BakedQuad>> sides,int bytes){}
 private static final Direction[] SIDES={Direction.DOWN,Direction.UP,Direction.NORTH,Direction.SOUTH,Direction.WEST,Direction.EAST,null};
 private static int index(Direction side){return side==null?6:side.get3DDataValue();}
 private static JsonObject json(String id,ResourceManager resources)throws IOException {var name=ResourceLocation.parse(id);var resource=resources.getResource(ResourceLocation.fromNamespaceAndPath(name.getNamespace(),"models/"+name.getPath()+".json")).orElseThrow();try(var reader=resource.openAsReader()){return JsonParser.parseReader(reader).getAsJsonObject();}}
 private static Map<String,String> textures(String id,ResourceManager resources,Map<String,Map<String,String>> cache,int depth)throws IOException {var known=cache.get(id);if(known!=null)return known;if(depth>16)throw new IOException("Cyclic engine model");var value=json(id,resources);var result=new HashMap<String,String>();if(value.has("parent"))result.putAll(textures(value.get("parent").getAsString(),resources,cache,depth+1));if(value.has("textures"))for(var entry:value.getAsJsonObject("textures").entrySet())result.put(entry.getKey(),entry.getValue().getAsString());var stable=Map.copyOf(result);cache.put(id,stable);return stable;}
 private static String texture(Map<String,String> textures,String ref){for(int n=0;n<16&&ref.startsWith("#");n++)ref=Objects.requireNonNull(textures.get(ref.substring(1)),"Missing engine texture");if(ref.startsWith("#"))throw new IllegalArgumentException("Cyclic engine texture");return ref;}
 private static float[] vector(JsonArray array){float[] result=new float[array.size()];for(int i=0;i<result.length;i++)result[i]=array.get(i).getAsFloat();return result;}
 private static boolean same(ResourceLocation id,ResourceManager resources)throws IOException {byte[] active;try(var stream=resources.getResource(id).orElseThrow().open()){active=stream.readAllBytes();}try(var stream=NativePropulsionModel.class.getResourceAsStream("/assets/"+id.getNamespace()+"/"+id.getPath())){return stream!=null&&Arrays.equals(active,stream.readAllBytes());}}
 private static boolean canonicalObject(String id,ResourceManager resources){try{var active=json(id,resources);var name=ResourceLocation.parse(id);JsonObject original;try(var reader=new InputStreamReader(Objects.requireNonNull(NativePropulsionModel.class.getResourceAsStream("/assets/"+name.getNamespace()+"/models/"+name.getPath()+".json")),StandardCharsets.UTF_8)){original=JsonParser.parseReader(reader).getAsJsonObject();}for(String field:List.of("loader","model","automatic_culling","shade_quads","flip_v","emissive_ambient"))if(!Objects.equals(active.get(field),original.get(field)))return false;var raw=ResourceLocation.parse(original.get("model").getAsString());if(!same(raw,resources))return false;try(var reader=resources.getResource(raw).orElseThrow().openAsReader()){String line;var text=new BufferedReader(reader);while((line=text.readLine())!=null)if(line.startsWith("mtllib ")){String path=raw.getPath();var material=ResourceLocation.fromNamespaceAndPath(raw.getNamespace(),path.substring(0,path.lastIndexOf('/')+1)+line.substring(7));if(!same(material,resources))return false;}}return true;}catch(IOException|RuntimeException unsupported){return false;}}
 public static final class Bake {
  private final Map<String,Source> sources;private final Map<String,TextureAtlasSprite> sprites;
  private NativeFlatWallModel.Bake materials;
  private final LinkedHashMap<Key,Mesh> meshes=new LinkedHashMap<>(32,.75F,true);private final WeakHashMap<NativePropulsionEntity.Visual,Key> bindings=new WeakHashMap<>();private int bytes;private long builds;
  Bake(Map<ModelResourceLocation,BakedModel> models,Function<Material,TextureAtlasSprite> textures,NativeFlatWallModel.Bake materials,ResourceManager resources){this.materials=materials;var sources=new HashMap<String,Source>();var sprites=new HashMap<String,TextureAtlasSprite>();Map<String,Map<String,String>> textureMaps=new HashMap<>();
   for(String id:NativePropulsionAssets.models()){var model=Objects.requireNonNull(models.get(ModelResourceLocation.standalone(ResourceLocation.parse(id))),id);var descriptor=NativePropulsionAssets.model(id);List<PropulsionBoxMesh.Face> boxes=List.of();boolean canonical=NativeDoorArtwork.isStatic(model);
    if(descriptor.kind().equals("obj"))canonical&=canonicalObject(id,resources);else{canonical&=NativeDoorArtwork.canonicalGeometry(id,resources);if(canonical)try{var mapped=textures(id,resources,textureMaps,0);var compiled=new ArrayList<PropulsionBoxMesh.Face>();for(var raw:NativeDoorArtwork.elements(id)){var element=raw.getAsJsonObject();if(element.has("rotation"))throw new IllegalArgumentException("Unfrozen engine element rotation");for(Direction side:Direction.values()){var faces=element.getAsJsonObject("faces");if(!faces.has(side.getName()))continue;var face=faces.getAsJsonObject(side.getName());String sprite=texture(mapped,face.get("texture").getAsString());compiled.add(new PropulsionBoxMesh.Face(sprite,vector(element.getAsJsonArray("from")),vector(element.getAsJsonArray("to")),side.get3DDataValue(),vector(face.getAsJsonArray("uv")),face.has("rotation")?face.get("rotation").getAsInt():0,face.has("cullface")?Objects.requireNonNull(Direction.byName(face.get("cullface").getAsString())).get3DDataValue():-1,face.has("tintindex")?face.get("tintindex").getAsInt():-1,!element.has("shade")||element.get("shade").getAsBoolean()));}}boxes=List.copyOf(compiled);}catch(IOException|RuntimeException unsupported){canonical=false;boxes=List.of();}}
    var source=new Source(model,boxes,descriptor.kind().equals("obj")?descriptor.geometry():List.of(),canonical);sources.put(id,source);if(canonical){for(var face:boxes)sprites.computeIfAbsent(face.sprite,name->textures.apply(new Material(TextureAtlas.LOCATION_BLOCKS,ResourceLocation.parse(name))));for(var face:source.objects)sprites.computeIfAbsent(face.sprite,name->textures.apply(new Material(TextureAtlas.LOCATION_BLOCKS,ResourceLocation.parse(name))));}
   }this.sources=Map.copyOf(sources);this.sprites=Map.copyOf(sprites);
  }
  synchronized void materials(NativeFlatWallModel.Bake materials){if(this.materials==null&&materials!=null){this.materials=materials;clear();}}
  private ProgrammableModel.MaterialSnapshot material(int choice){if(materials==null)return null;var result=materials.surfaces.get(choice);if(result!=null)return result;var custom=com.vandorlabs.neoforge.client.NativeBlockMaterials.material(choice);if(custom!=null)return new ProgrammableModel.MaterialSnapshot(custom.lower(),1,1);return materials.surfaces.get(ModernFinishCatalog.storedChoice(choice));}
  private static PropulsionObjMesh.Sprite image(TextureAtlasSprite sprite){return new PropulsionObjMesh.Sprite(){public float minU(){return sprite.getU0();}public float maxU(){return sprite.getU1();}public float minV(){return sprite.getV0();}public float maxV(){return sprite.getV1();}public int width(){return sprite.contents().width();}public int height(){return sprite.contents().height();}};}
  private interface Template {float position(int vertex,int axis);float normal(int axis);}
  private static int[] template(List<BakedQuad> original,TextureAtlasSprite sprite,Template face){BakedQuad best=null;double score=Double.POSITIVE_INFINITY;int[] map=new int[4],chosen=new int[4];boolean[] used=new boolean[4];for(var quad:original){if(quad.getSprite()!=sprite)continue;int[] vertices=quad.getVertices();int stride=vertices.length/4;if(vertices.length%4!=0||stride<8)continue;Arrays.fill(used,false);double error=0;for(int v=0;v<4;v++){int index=-1;double distance=Double.POSITIVE_INFINITY;for(int w=0;w<4;w++)if(!used[w]){double delta=0;for(int a=0;a<3;a++)delta+=Math.abs(face.position(v,a)-Float.intBitsToFloat(vertices[w*stride+a]));if(delta<distance){distance=delta;index=w;}}used[index]=true;map[v]=index;error+=distance*1000;}int normal=vertices[map[0]*stride+7];for(int a=0;a<3;a++)error+=Math.abs(face.normal(a)-(byte)(normal>>>(a*8))/127F)*.0001;if(error<score){score=error;best=quad;System.arraycopy(map,0,chosen,0,4);}}if(best!=null&&score<.01){int[] source=best.getVertices(),result=new int[source.length];int stride=result.length/4;for(int v=0;v<4;v++)System.arraycopy(source,chosen[v]*stride,result,v*stride,stride);return result;}int[] result=new int[32];for(int v=0;v<4;v++)result[v*8+3]=-1;return result;}

  private Mesh build(Key key,BlockState state,RandomSource random,ModelData data,RenderType renderType){var source=sources.get(key.variant.model());if(source==null)return new Mesh(List.of(List.of(),List.of(),List.of(),List.of(),List.of(),List.of(),List.of()),128);List<List<BakedQuad>> buckets=new ArrayList<>(7);for(int i=0;i<7;i++)buckets.add(new ArrayList<>());int x=key.variant.x(),y=key.variant.y();
   if(source.canonical){var originals=source.model.getQuads(state,null,random,data,renderType);for(var face:source.boxes){var sprite=sprites.get(face.sprite);int[] vertices=template(originals,sprite,new Template(){public float position(int v,int a){return face.position(v,a);}public float normal(int a){return a==0?PropulsionEmission.dx(face.direction):a==1?PropulsionEmission.dy(face.direction):PropulsionEmission.dz(face.direction);}});int direction=PropulsionBoxMesh.bake(face,x,y,image(sprite),vertices);buckets.get(face.cull<0?6:rotated(face.cull,x,y)).add(new BakedQuad(vertices,face.tint,Direction.from3DDataValue(direction),sprite,face.shade,source.model.useAmbientOcclusion()));}for(var face:source.objects){var sprite=sprites.get(face.sprite);int[] vertices=template(originals,sprite,new Template(){public float position(int v,int a){return face.position(v,a);}public float normal(int a){return face.normal(a);}});int direction=PropulsionObjMesh.bake(face,x,y,image(sprite),vertices);buckets.get(6).add(new BakedQuad(vertices,-1,Direction.from3DDataValue(direction),sprite,true,source.model.useAmbientOcclusion()));}}
   else for(Direction side:SIDES)for(var quad:source.model.getQuads(state,side,random,data,renderType)){int[] vertices=quad.getVertices().clone();PropulsionModelRotation.quad(vertices,x,y,false);buckets.get(side==null?6:rotated(side.get3DDataValue(),x,y)).add(new BakedQuad(vertices,quad.getTintIndex(),Direction.from3DDataValue(rotated(quad.getDirection().get3DDataValue(),x,y)),quad.getSprite(),quad.isShade(),quad.hasAmbientOcclusion()));}
   var replacement=key.material==9?null:material(key.material);int cost=192;for(int i=0;i<7;i++){var quads=NativePropulsionMaterials.apply(buckets.get(i),replacement==null?9:key.material,key.brightness,replacement==null?null:replacement.sprite(),replacement==null?1:replacement.usedU(),replacement==null?1:replacement.usedV());buckets.set(i,List.copyOf(quads));cost+=32;for(var q:quads)cost+=96+q.getVertices().length*4;}builds++;return new Mesh(List.copyOf(buckets),cost);
  }
  private static int rotated(int face,int x,int y){float a=PropulsionEmission.dx(face),b=PropulsionEmission.dy(face),c=PropulsionEmission.dz(face);return Direction.getNearest(PropulsionModelRotation.normal(x,y,0,a,b,c),PropulsionModelRotation.normal(x,y,1,a,b,c),PropulsionModelRotation.normal(x,y,2,a,b,c)).get3DDataValue();}
  private Key key(NativePropulsionEntity.Visual visual){var key=bindings.get(visual);if(key==null){key=new Key(NativePropulsionAssets.variant(visual),visual.sideTexture(),visual.brightness());if(bindings.size()>=BINDINGS)bindings.clear();bindings.put(visual,key);}return key;}
  public synchronized List<BakedQuad> quads(NativePropulsionEntity.Visual visual,BlockState state,Direction side,RandomSource random,ModelData data,RenderType renderType){var key=key(visual);var source=sources.get(key.variant.model());if(source==null)return List.of();boolean cached=NativeDoorArtwork.isStatic(source.model);var found=cached?meshes.get(key):null;if(found==null){found=build(key,state,random,data,renderType);if(cached&&found.bytes<=BUDGET){meshes.put(key,found);bytes+=found.bytes;while(bytes>BUDGET){var iterator=meshes.values().iterator();bytes-=iterator.next().bytes;iterator.remove();}}}return found.sides.get(index(side));}

  public synchronized long retainedBytes(){return bytes;}public synchronized long meshBuilds(){return builds;}public synchronized void clear(){meshes.clear();bindings.clear();bytes=0;}
  synchronized BakedModel source(NativePropulsionEntity.Visual visual){var model=sources.get(key(visual).variant.model());return model==null?null:model.model;}
 }
 private record Prepared(long generation,Bake bake){}
 private static final AtomicLong GENERATION=new AtomicLong();private static final com.google.common.cache.Cache<Object,Prepared> PENDING=com.google.common.cache.CacheBuilder.newBuilder().weakKeys().maximumSize(2).build();private static volatile Prepared active;
 public static Bake prepare(Object bakery,Map<ModelResourceLocation,BakedModel> models,Function<Material,TextureAtlasSprite> textures,NativeFlatWallModel.Bake materials,ResourceManager resources){if(!NativePropulsionResources.active())return null;var bake=new Bake(models,textures,materials,resources);PENDING.put(bakery,new Prepared(GENERATION.incrementAndGet(),bake));return bake;}
 @SubscribeEvent(priority=EventPriority.LOWEST)public static synchronized void completed(ModelEvent.BakingCompleted event){var prepared=PENDING.getIfPresent(event.getModelBakery());PENDING.invalidate(event.getModelBakery());if(prepared!=null&&(active==null||prepared.generation>active.generation)){prepared.bake.materials(NativePanelPlaybackRenderer.currentBake());active=prepared;}}
 public static Bake currentBake(){return active==null?null:active.bake;}
 public static BakedModel wrap(BakedModel original,Bake bake){return bake==null?original:new Wrapped(original,bake);}
 private static final class Wrapped extends BakedModelWrapper<BakedModel>{private final Bake bake;Wrapped(BakedModel original,Bake bake){super(original);this.bake=bake;}private static NativePropulsionEntity.Visual visual(BlockState state,ModelData data){var known=data.get(NativePropulsionEntity.VISUAL);if(known!=null)return known;if(state==null||!(state.getBlock() instanceof NativePropulsionBlock block))return null;return new NativePropulsionEntity.Visual(block.definition(),state.getValue(NativePropulsionBlock.FACING),state.getValue(NativePropulsionBlock.POWERED),15,9,0,false,true,NativePropulsionEntity.Part.SINGLE,false);}
  @Override public List<BakedQuad> getQuads(BlockState state,Direction side,RandomSource random,ModelData data,RenderType renderType){var visual=visual(state,data);return visual==null?originalModel.getQuads(state,side,random,data,renderType):bake.quads(visual,state,side,random,data,renderType);}
  @Override public net.neoforged.neoforge.common.util.TriState useAmbientOcclusion(BlockState state,ModelData data,RenderType type){var visual=visual(state,data);var source=visual==null?null:bake.source(visual);return source==null?originalModel.useAmbientOcclusion(state,data,type):source.useAmbientOcclusion(state,data,type);}
  @Override public TextureAtlasSprite getParticleIcon(ModelData data){var visual=data.get(NativePropulsionEntity.VISUAL);var source=visual==null?null:bake.source(visual);return source==null?originalModel.getParticleIcon(data):source.getParticleIcon(data);}
  @Override public net.neoforged.neoforge.client.ChunkRenderTypeSet getRenderTypes(BlockState state,RandomSource random,ModelData data){var visual=visual(state,data);var source=visual==null?null:bake.source(visual);return source==null?originalModel.getRenderTypes(state,random,data):source.getRenderTypes(state,random,data);}
 }
 @EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)public static final class Worlds{@SubscribeEvent public static void unload(net.neoforged.neoforge.event.level.LevelEvent.Unload event){var value=active;if(value!=null)value.bake.clear();}}
}
